'use client'
import dynamic from 'next/dynamic'
import { useEffect, useState } from 'react'
import { Loader2, X, Plane, Navigation, Gauge, Mountain } from 'lucide-react'
import { useTheme } from 'next-themes'

const LiveMap = dynamic(() => import('@/components/tracking/live-map'), { ssr: false, loading: () => (
  <div className="flex items-center justify-center h-full min-h-[420px] bg-slate-900 rounded-xl border border-slate-800">
    <Loader2 className="w-8 h-8 animate-spin text-sky-400" />
  </div>
)})

interface LiveFlight {
  id: string
  callsign: string
  aircraftType?: string | null
  depIcao: string
  arrIcao: string
  lat: number
  lng: number
  altitude: number
  groundSpeed: number
  heading: number
  phase: string
  pilot: { callsign: string; firstName: string; lastName: string }
}

interface AirportPoint {
  icao: string
  lat: number
  lng: number
  name: string
}

export default function TrackingPage() {
  const { theme } = useTheme()
  const [mounted, setMounted] = useState(false)
  const [flights, setFlights] = useState<LiveFlight[]>([])
  const [airportsByIcao, setAirportsByIcao] = useState<Record<string, AirportPoint>>({})
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState<string | null>(null)
  const [aircraftPhotoUrl, setAircraftPhotoUrl] = useState<string | null>(null)
  const [aircraftPhotoLoading, setAircraftPhotoLoading] = useState(false)
  const mapTheme = theme === 'light' ? 'light' : 'dark'
  const selectedFlight = selected ? flights.find((flight) => flight.id === selected) ?? null : null

  const depAirport = selectedFlight ? airportsByIcao[selectedFlight.depIcao.toUpperCase()] : undefined
  const arrAirport = selectedFlight ? airportsByIcao[selectedFlight.arrIcao.toUpperCase()] : undefined

  const fetchFlights = async () => {
    const liveRes = await fetch('/api/tracking/live')

    if (liveRes.ok) {
      const liveFlights: LiveFlight[] = await liveRes.json()
      setFlights(liveFlights)

      const icaos = Array.from(
        new Set(
          liveFlights
            .flatMap((flight) => [flight.depIcao, flight.arrIcao])
            .map((icao) => icao.trim().toUpperCase())
            .filter((icao) => icao.length === 4),
        ),
      )

      if (icaos.length > 0) {
        const airportsRes = await fetch(`/api/tracking/airports?icao=${encodeURIComponent(icaos.join(','))}`)
        if (airportsRes.ok) {
          const airports: AirportPoint[] = await airportsRes.json()
          const next = airports.reduce<Record<string, AirportPoint>>((acc, airport) => {
            acc[airport.icao.toUpperCase()] = airport
            return acc
          }, {})
          setAirportsByIcao(next)
        }
      }
    }
    setLoading(false)
  }

  useEffect(() => {
    setMounted(true)
  }, [])

  useEffect(() => {
    fetchFlights()
    const interval = setInterval(fetchFlights, 5000)
    return () => clearInterval(interval)
  }, [])

  useEffect(() => {
    if (!selectedFlight) {
      setAircraftPhotoUrl(null)
      setAircraftPhotoLoading(false)
      return
    }

    const controller = new AbortController()

    const loadAircraftPhoto = async () => {
      setAircraftPhotoLoading(true)
      try {
        const response = await fetch(
          `/api/tracking/aircraft-photo?callsign=${encodeURIComponent(selectedFlight.callsign)}&depIcao=${encodeURIComponent(selectedFlight.depIcao)}&arrIcao=${encodeURIComponent(selectedFlight.arrIcao)}`,
          { signal: controller.signal },
        )
        if (!response.ok) {
          setAircraftPhotoUrl(null)
          return
        }

        const payload: { photoUrl?: string | null } = await response.json()
        setAircraftPhotoUrl(payload.photoUrl ?? null)
      } catch {
        if (!controller.signal.aborted) {
          setAircraftPhotoUrl(null)
        }
      } finally {
        if (!controller.signal.aborted) {
          setAircraftPhotoLoading(false)
        }
      }
    }

    loadAircraftPhoto()

    return () => {
      controller.abort()
    }
  }, [selectedFlight?.id, selectedFlight?.callsign, selectedFlight?.depIcao, selectedFlight?.arrIcao])

  if (!mounted) {
    return (
      <div className="h-[calc(100dvh-8rem)] sm:h-[calc(100dvh-9rem)] lg:h-[calc(100dvh-10rem)] overflow-hidden">
        <div className="h-full min-h-[420px] bg-slate-900 rounded-xl border border-slate-800" />
      </div>
    )
  }

  return (
    <div className="h-[calc(100dvh-8rem)] sm:h-[calc(100dvh-9rem)] lg:h-[calc(100dvh-10rem)] overflow-hidden">
      {/* Map */}
      <div className="relative h-full">
        <LiveMap flights={flights} airportsByIcao={airportsByIcao} selectedId={selected} onSelect={setSelected} theme={mapTheme} />

        {selectedFlight ? (
          <aside className="absolute top-4 left-4 z-20 w-[320px] max-w-[calc(100%-2rem)] rounded-xl border border-slate-200/80 dark:border-slate-700 bg-white/95 dark:bg-slate-900/95 backdrop-blur shadow-xl">
            <div className="relative h-36 border-b border-slate-200 dark:border-slate-700 overflow-hidden rounded-t-xl bg-slate-100 dark:bg-slate-800">
              {aircraftPhotoUrl ? (
                <img
                  src={aircraftPhotoUrl}
                  alt={`${selectedFlight.callsign} aircraft`}
                  className="w-full h-full object-cover"
                  loading="lazy"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                  {aircraftPhotoLoading ? (
                    <Loader2 className="w-6 h-6 animate-spin text-slate-400" />
                  ) : (
                    <Plane className="w-10 h-10 text-slate-400" />
                  )}
                </div>
              )}
              <div className="absolute inset-0 bg-gradient-to-t from-black/45 via-black/10 to-transparent" />
              <button
                onClick={() => setSelected(null)}
                className="absolute top-2 right-2 z-10 inline-flex items-center justify-center rounded-md border border-white/35 bg-black/25 p-1.5 text-white/90 hover:text-white"
                aria-label="Close flight details"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="px-4 py-3 border-b border-slate-200 dark:border-slate-700">
              <div>
                <div className="text-xs uppercase tracking-wide text-slate-500">Live Flight</div>
                <h2 className="text-xl font-bold text-slate-900 dark:text-white leading-tight">{selectedFlight.callsign}</h2>
                <p className="text-sm text-slate-500">{selectedFlight.pilot.firstName} {selectedFlight.pilot.lastName}</p>
              </div>
            </div>

            <div className="p-4 space-y-4">
              <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-3 bg-slate-50 dark:bg-slate-800/40">
                <div className="flex items-center justify-between gap-3 text-sm">
                  <div>
                    <div className="text-slate-500">Departure</div>
                    <div className="font-semibold text-slate-900 dark:text-white">{selectedFlight.depIcao}</div>
                    <div className="text-xs text-slate-500 truncate">{depAirport?.name ?? 'Unknown airport'}</div>
                  </div>
                  <Plane className="w-4 h-4 text-sky-500" />
                  <div className="text-right">
                    <div className="text-slate-500">Arrival</div>
                    <div className="font-semibold text-slate-900 dark:text-white">{selectedFlight.arrIcao}</div>
                    <div className="text-xs text-slate-500 truncate">{arrAirport?.name ?? 'Unknown airport'}</div>
                  </div>
                </div>
              </div>

              <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-3 bg-slate-50 dark:bg-slate-800/40">
                <div className="text-slate-500 text-xs uppercase tracking-wide">Aircraft</div>
                <div className="text-base font-semibold text-slate-900 dark:text-white mt-1">{selectedFlight.aircraftType ?? 'Unknown type'}</div>
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-3">
                  <div className="flex items-center gap-2 text-slate-500 text-xs uppercase tracking-wide">
                    <Mountain className="w-3.5 h-3.5" /> Altitude
                  </div>
                  <div className="text-base font-semibold text-slate-900 dark:text-white mt-1">{selectedFlight.altitude.toLocaleString()} ft</div>
                </div>
                <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-3">
                  <div className="flex items-center gap-2 text-slate-500 text-xs uppercase tracking-wide">
                    <Gauge className="w-3.5 h-3.5" /> Ground Speed
                  </div>
                  <div className="text-base font-semibold text-slate-900 dark:text-white mt-1">{selectedFlight.groundSpeed} kts</div>
                </div>
                <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-3">
                  <div className="flex items-center gap-2 text-slate-500 text-xs uppercase tracking-wide">
                    <Navigation className="w-3.5 h-3.5" /> Heading
                  </div>
                  <div className="text-base font-semibold text-slate-900 dark:text-white mt-1">{selectedFlight.heading}&deg;</div>
                </div>
                <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-3">
                  <div className="text-slate-500 text-xs uppercase tracking-wide">Phase</div>
                  <div className="text-base font-semibold text-slate-900 dark:text-white mt-1">{selectedFlight.phase}</div>
                </div>
              </div>
            </div>
          </aside>
        ) : null}
      </div>
    </div>
  )
}
